"""Revise the system scope and offline interface without changing experiment data."""
from pathlib import Path
import re
import json

ROOT = Path(__file__).resolve().parents[1]

def save(path, text):
    (ROOT / path).write_text(text, encoding='utf-8', newline='\n')

def replace_once(text, old, new):
    assert old in text, old[:120]
    return text.replace(old, new, 1)

formal = (ROOT/'application/正式模板正文.md').read_text(encoding='utf-8')
formal = replace_once(formal, '为支管检查提供位置范围、变化证据和处理记录。', '贯通支管监测、告警核查、处置复测与记录归档，为运行维护提供变化证据。')
formal = replace_once(formal, '接收端保存事件证据，管理者据此核查并记录处理结果。', '接收端保存事件证据，管理者据此核查、记录处置并复测；复测证据不足时保留待检查状态。')
formal = replace_once(formal, '系统闭环截至管理确认，自动阀控不列入本期基础任务。', '系统运行链贯通监测、告警、人工核查、处置记录和同工况复测；软件按证据归档事件，自动阀控不列入本期基础任务。人工标记已查看不能代替异常解除或实物修复。')
formal = replace_once(formal, '管径、器件包络及接头尺寸暂定，采购后须核定装配、检修空间和防护；尚未制造或实测。', '该模型用于实施前核对水路、测点及检修空间，为标定、可控故障注入和重复实验提供布置依据；900×520mm不是必须采购的定制平台规格。管径、器件包络及接头尺寸暂定，采购后须核定，尚未制造或实测。')
formal = replace_once(formal, '#### 2.2 节点硬件与数据采集', '泄漏出口采用自由出流，独立收集装置不得形成背压或淹没出口。图中小容器仅表示收集位置，不能直接用于长时间计量；实际按最大泄漏流量与计量时长确定容积，并配置托盘和回水操作。供水稳定性、排气、流量计要求的安装条件及电子盒与水路的隔离需在装配前核查。田间部署保留P0/P1/Q与节点接口，另设计固定和防护，不搬用整套实验台架作为田间成品。\n\n#### 2.2 节点硬件与数据采集')
formal = replace_once(formal, '本地Web拟提供设备档案、支管位置示意、P0/P1/Q趋势、事件证据、质量状态、处理确认、历史回放与CSV导出。', '本地Web拟提供设备档案、支管位置示意、P0/P1/Q趋势、事件证据、质量状态、核查处置、复测归档、历史回放与CSV导出。')
formal = replace_once(formal, '已有离线页面完成合成回放与交互演示，其实际管理面板局部截图见图8。', '已有离线页面提供合成回放和人工维护流程演示，浏览器本地记录与导出用于检查交互设计，其管理面板局部截图见图8；这类演示记录不属于实物维护证据。')
formal = replace_once(formal, '以事件记录贯通节点判定、接收存储和管理确认。', '以事件记录贯通节点判定、接收存储和人工维护。事件以设备、掉电会话、序号标识，另关联试次、配置及健康参照版本；测量、本地提示、远端接收和人工操作时间分开记录，操作标签独立保存。')
formal = replace_once(formal, '### 6 项目目标与分层实验', '维护流程区分待核查、已查看、已记录处置、待复测和已归档。核查记录须说明供压、阀态及传感器检查结果；处置后保留同工况复测窗口、参考读数和前后变化。数据无效、工况不可比或异常仍持续时不得标记恢复。通信ACK只确认接收持久化，网页的已查看与人工归档分别留痕。验收安排一次误报核查和两类等效故障的处置复测，检查日志能否重建全过程。\n\n### 6 项目目标与分层实验')
formal = replace_once(formal, '| 系统集成 | 节点、接收端及本地Web贯通 | 事件可追溯、离线与无效状态、回放导出、处理记录 |', '| 系统集成 | 节点、接收端、本地Web及维护复测贯通 | 事件标识与版本、离线/无效、处置前后记录、回放导出 |')
formal = replace_once(formal, '## 四、国、内外研究现状和发展动态', '''### 8 后续研究方向与扩展条件

优先延伸为跨工况诊断与低成本测量边界研究。在完成本期标定及单区段验证后，利用同一台架增加健康负载档位和独立批次，比较冻结参照、压力归一化与少量健康重标定；按整档压力、负载或日期留出验证，评价重标定成本、误报及可检出程度。健康压力—流量关系依据实测拟合，必要时修订平方根指数或采用经验曲线，不将未知负载与泄漏的同形误认为算法可消除的问题[2,12]。这一路线不依赖先取得田间故障数据，可作为论文主线的进一步深化。

第二方向为多支管共同供压扰动与局部异常区分。只有新增实际节点、公共供压参照和对齐日志后，才研究共性变化与局部变化的判别，并联合测试节点竞争、事件拥塞和告警公平性[10,13]。B支路当前只制造正常负载切换，不能代表已完成多节点协同。新增节点与现场部署须另核定经费和许可。

第三方向为长期运行与维护复测。通过真实维护前后配对记录，研究健康参照随安装、温漂及负载变化的稳定性，评价异常恢复判断和人工核查工作量[12,16]。本期先完成软件留痕及台架配对验证；长期田间标签与水质机理研究列为后续条件任务。由此形成从单区段可信测量、跨工况可迁移诊断到多支管运行维护的连续研究路线，各阶段以独立证据决定是否推进。

## 四、国、内外研究现状和发展动态''')
formal = replace_once(formal, '用户能够查看异常区段、变化证据和处理记录。', '用户能够查看异常区段、变化证据以及核查、处置和复测记录。跨工况迁移与多支管共同扰动为后续研究预留了可检验问题和数据接口。')
formal = replace_once(formal, '可靠接收、查看确认及数据导出。', '可靠接收、人工核查、处置复测及数据导出。')
formal = replace_once(formal, '图8是当前离线网页实际截图，支持合成回放、质量状态及确认演示；实际设备接入与日志持久化尚未实现。', '图8是当前离线网页实际截图，支持合成回放、质量状态及维护流程演示，演示记录可在浏览器本地保存并导出；真实设备接入、接收数据库与实物维护记录尚未实现。')
save('application/正式模板正文.md', formal)

scope = (ROOT/'docs/项目范围与三阶段执行方案.md').read_text(encoding='utf-8')
scope = scope.replace('版本1.3', '版本1.4')
scope = scope.replace('建议、确认记录与回放。', '建议、核查、处置、同工况复测记录与回放。')
scope = scope.replace('事件确认、趋势、回放、导出、质量状态', '核查处置、复测归档、趋势、回放、导出、质量状态')
scope = scope.replace('## 当前一个月申报工作', '''## 台架与田间安装的用途

三维模型是用于核对装配布置的实验平台方案，服务于标定、共同供压与正常切换、可控故障注入、独立参考测量和重复操作。先用现有板材与管夹搭最小夹具，再依据实际器件调整尺寸；全套定制机架不作为2000元基础采购。小型收集杯是位置示意，实际根据泄漏流量和计时长度选择有余量的量具或称重容器，维持自由出流，避免溢流、背压和电气溅水。

田间设备为固定在实际管路上的传感器与受保护节点；安装间距、管件压损、流量计条件、维护空间和防护须现场核对。台架几何有效性不证明耐压、防水、制造可行或田间适用。

## 系统运行与维护记录

系统贯通监测、告警、人工核查、处置、复测和归档。ACK表示远端保存事件，已查看表示人工浏览，归档要求有可比工况下的复测记录；三者各记时间。无效、离线及证据不足时保留待检查。事件关联设备/会话/序号、试次、配置和健康参照版本，独立标签另存，避免以界面状态代替故障真值。

当前网页实现的是合成回放与浏览器本地维护流程演示，可以保存演示备注、复测结论并导出；不连接硬件，也没有真实维修记录。大创实施期将串口、SQLite、节点日志及独立参考接入该流程。

## 当前一个月申报工作''')
scope = scope.replace('## 预算和人力约束', '''## 可延伸的研究路线

第一优先级为跨工况与跨负载迁移。在标定和单区段验证完成后，增加健康负载档位，以整档压力、负载或日期作为留出单位，比较冻结参照、压力归一化与少量健康重标定，报告检出边界和重标定成本。它能利用现有台架深化论文，但新增样本及跨负载验证不属于现有480次噪声回放。

第二优先级为多支管共同供压扰动与局部异常区分。需要至少两实际节点、公共供压参照、时间对齐和补充经费，再检验共性变化判别及无线竞争下的告警公平性。第三方向为长期维护前后配对研究，必须有真实复测与维护记录。后续是否推进取决于测量、标签和资源质量；云平台、太阳能与自动阀控不代替上述研究问题。

## 预算和人力约束''')
save('docs/项目范围与三阶段执行方案.md', scope)

