oldack="$('diag-ack').onclick=()=>{$('diag-ack-result').textContent='已查看当前演示状态（模型时刻 '+$('diag-time').value+' s）。没有向硬件发送命令，未形成实际处理记录。';};diagnosisView();"
newack=r'''const maintenanceStorageKey='drip-research-demo-maintenance-v1';let maintenanceRecords=[],maintenanceStorage='浏览器本地保存';try{maintenanceRecords=JSON.parse(localStorage.getItem(maintenanceStorageKey)||'[]');if(!Array.isArray(maintenanceRecords))maintenanceRecords=[]}catch{maintenanceStorage='本次页面暂存（浏览器未提供本地保存）'}
function maintenanceKey(){return [$('diag-case').value,$('diag-noise').value,$('diag-quality').value,$('diag-time').value].join(':')}
function maintenanceEntry(){return maintenanceRecords.find(r=>r.key===maintenanceKey())}
function persistMaintenance(){try{localStorage.setItem(maintenanceStorageKey,JSON.stringify(maintenanceRecords))}catch{maintenanceStorage='本次页面暂存（浏览器未提供本地保存）'}}
function renderMaintenance(){const r=maintenanceEntry();$('diag-ack-result').textContent=r&&r.history.some(h=>h.action==='viewed')?'已查看当前演示状态；操作时间单独记录，尚不能据此认定修复。':'未记录当前状态查看。';$('maintenance-note').value=r?.note||'';$('maintenance-proof').value=r?.proof||'';$('maintenance-result').value=r?.result||'pending';$('maintenance-status').textContent=(r?.stage||'待核查')+' · '+maintenanceStorage+' · 非实物记录';const log=$('maintenance-log');log.replaceChildren();for(const h of r?.history||[]){const li=document.createElement('li');li.textContent=h.at.replace('T',' ').slice(0,19)+' / '+h.label;log.append(li)}}
function ensureMaintenanceEntry(){let r=maintenanceEntry();if(!r){r={key:maintenanceKey(),source:'synthetic_ui_demo',device_id:'demo-A',scenario:$('diag-case').value,noise:$('diag-noise').value,quality:$('diag-quality').value,model_time_s:Number($('diag-time').value),stage:'待核查',result:'pending',note:'',proof:'',history:[]};maintenanceRecords.push(r)}return r}
$('diag-ack').onclick=()=>{const r=ensureMaintenanceEntry();if(r.stage==='待核查')r.stage='已查看';r.history.push({action:'viewed',label:'人工已查看（演示）',at:new Date().toISOString()});persistMaintenance();renderMaintenance()};
$('maintenance-save').onclick=()=>{const note=$('maintenance-note').value.trim(),proof=$('maintenance-proof').value.trim(),result=$('maintenance-result').value;const r=maintenanceEntry();if(!r||!r.history.some(h=>h.action==='viewed')){$('maintenance-status').textContent='先记录已查看，再记录核查处置。';return}if(!note){$('maintenance-status').textContent='请填写核查与处置备注。';$('maintenance-note').focus();return}if(result!=='pending'&&!proof){$('maintenance-status').textContent='请填写复测依据或待检查原因。';$('maintenance-proof').focus();return}if(result==='recovered'&&$('diag-quality').value!=='model'){$('maintenance-status').textContent='离线或数据无效时，不允许记录恢复归档。';return}r.note=note;r.proof=proof;r.result=result;r.stage=result==='recovered'?'已归档（人工演示结论）':result==='pending'?'已记录处置 · 待复测':'复测未通过 · 待检查';r.history.push({action:'maintenance_saved',label:r.stage,at:new Date().toISOString()});persistMaintenance();renderMaintenance()};
$('maintenance-export').onclick=()=>{const records={classification:'synthetic_ui_demo_not_physical_maintenance',exported_at:new Date().toISOString(),records:maintenanceRecords};const blob=new Blob([JSON.stringify(records,null,2)],{type:'application/json;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='maintenance-demo-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};diagnosisView();
const firstPage=location.hash.slice(1);if(firstPage&&$(firstPage))navigate(firstPage);window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));'''
portal=replace_once(portal,oldack,newack)
extension='''<div class="stage"><b>后续研究：从一个区段走向可迁移诊断</b><p>先完成本期真实标定与独立验证，再逐级扩展；页面上的研究方向均为拟开展任务。</p><div class="scroll"><table><thead><tr><th>优先级</th><th>研究问题</th><th>进入条件与评价</th></tr></thead><tbody><tr><td>01 / 跨工况</td><td>换压力、负载或日期，健康参照和诊断能否迁移？</td><td>现有台架加健康档位；整档留出，比较误报、检出边界与重标定成本</td></tr><tr><td>02 / 多支管</td><td>共同供压下降与局部异常能否区分？</td><td>新增实际节点、公共供压参照、对齐日志；验证无线竞争及告警公平性</td></tr><tr><td>03 / 长期维护</td><td>处置前后是否恢复，健康参照如何保持可信？</td><td>真实配对复测与长期标签；比较恢复判断和人工核查工作量</td></tr></tbody></table></div><p class="fine">三维台架服务于标定和故障注入。田间安装采用实际管路上的传感器与防护节点，不能由台架模型推断现场性能。</p><a href="../docs/系统定位与后续研究路线.md">查看系统定位与研究延伸依据 ↗</a></div>'''
pos=portal.index('<section id="slides"')
before=portal[:pos];idx=before.rfind('</section>');portal=before[:idx]+extension+before[idx:]+portal[pos:]
save('scripts/portal.template.html', portal)

